pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, uint8 seed) public {
        address owner = c.Owner();
        amount = bound(amount, 1, type(uint128).max);
        address funder = address(uint160(uint256(keccak256(abi.encodePacked(seed, uint8(1))))));
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");
        uint256 balBefore = address(c).balance;
        vm.prank(owner);
        try c.withdraw() {
            uint256 balAfter = address(c).balance;
            assertTrue(balAfter < balBefore);
        } catch {
        }
    }
}
